const canvas=document.getElementById('battle'),ctx=canvas.getContext('2d');
const moneyEl=document.getElementById('money'),playerHpEl=document.getElementById('player-hp'),cards=[...document.querySelectorAll('.unit-card')],result=document.getElementById('result'),resultTitle=document.getElementById('result-title'),resultCopy=document.getElementById('result-copy'),toastEl=document.getElementById('toast');
const TYPES={soldier:{cost:20,hp:34,speed:57,range:145,damage:9,rate:.82,shotSpeed:430,kind:'bullet',size:1},tank:{cost:50,hp:145,speed:24,range:205,damage:27,rate:2.05,shotSpeed:290,kind:'shell',size:1.55,splash:62},artillery:{cost:80,hp:86,speed:13,range:365,damage:40,rate:3.1,shotSpeed:205,kind:'arc',size:1.35,splash:76}};
let w=0,h=0,dpr=1,units=[],shots=[],particles=[],texts=[],money=60,playerHp=100,enemyHp=100,elapsed=0,spawnTimer=5,finished=false,last=0,toastTimer=0,shake=0;
const groundY=()=>h*.82;
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function rand(a,b){return a+Math.random()*(b-a)}
function baseX(team){return team? w-61:61}
function unitY(u){return groundY()-(u.type==='soldier'?31:u.type==='tank'?31:35)}
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),1500)}
function deploy(type){if(finished)return;const spec=TYPES[type];if(money<spec.cost){toast('Not enough supply — wait for the next drop.');return}if(units.filter(u=>u.team===0).length>=16){toast('Frontline is full.');return}money-=spec.cost;spawn(0,type);updateHud();}
function spawn(team,type){const spec=TYPES[type];units.push({id:Math.random(),team,type,hp:spec.hp,maxHp:spec.hp,x:team?baseX(1)-42:baseX(0)+42,cool:rand(.15,.55),anim:rand(0,6),flash:0})}
cards.forEach(b=>b.addEventListener('click',()=>deploy(b.dataset.unit)));
document.addEventListener('keydown',e=>{if(e.key==='1')deploy('soldier');if(e.key==='2')deploy('tank');if(e.key==='3')deploy('artillery');if((e.key==='r'||e.key==='R')&&finished)reset()});
document.getElementById('restart').addEventListener('click',reset);
function updateHud(){moneyEl.textContent='$'+Math.floor(money);playerHpEl.textContent=Math.max(0,Math.ceil(playerHp))+'%';playerHpEl.style.color=playerHp<30?'#ff8981':'';cards.forEach(b=>b.disabled=finished||money<TYPES[b.dataset.unit].cost)}
function endGame(win){if(finished)return;finished=true;resultTitle.textContent=win?'VICTORY':'DEFEAT';resultTitle.className='result-title '+(win?'win':'loss');resultCopy.textContent=win?'The enemy line has fallen. The last light is yours.':'Your stronghold has fallen. Regroup and try another strategy.';result.classList.add('show');updateHud()}
function reset(){units=[];shots=[];particles=[];texts=[];money=60;playerHp=100;enemyHp=100;elapsed=0;spawnTimer=4.5;finished=false;last=performance.now();result.classList.remove('show');updateHud();toast('Command ready. Hold the line.')}
function chooseTarget(u){const foes=units.filter(v=>v.team!==u.team&&v.hp>0).sort((a,b)=>Math.abs(a.x-u.x)-Math.abs(b.x-u.x));const foe=foes[0],dir=u.team? -1:1,range=TYPES[u.type].range;if(foe&&Math.abs(foe.x-u.x)<=range+14)return {unit:foe,x:foe.x,y:unitY(foe)-12};const bx=baseX(!u.team),dist=Math.abs(bx-u.x);if(dist<=range+58)return {base:!u.team,x:bx,y:groundY()-82};return null}
function fire(u,target){const spec=TYPES[u.type],direction=u.team?-1:1,fromX=u.x+direction*(u.type==='tank'?28:16),fromY=unitY(u)-(u.type==='soldier'?17:u.type==='tank'?32:28);const d=Math.abs(target.x-fromX),flight=spec.kind==='arc'?Math.max(.5,d/spec.shotSpeed):Math.max(.12,d/spec.shotSpeed);shots.push({team:u.team,kind:spec.kind,x:fromX,y:fromY,sx:fromX,sy:fromY,tx:target.x,ty:target.y,flight,age:0,targetUnit:target.unit,targetBase:target.base,damage:spec.damage,splash:spec.splash||0,dir:direction});u.cool=spec.rate;u.flash=.09}
function damageTarget(target,amount,team){if(target&&target.hp>0){target.hp=Math.max(0,target.hp-amount);target.flash=.14;if(target.hp<=0){burst(target.x,unitY(target),target.type==='tank'?15:9,'#ffb37b');if(target.team===0)shake=5}}}
function burst(x,y,count,color){for(let i=0;i<count;i++)particles.push({x,y,vx:rand(-72,72),vy:rand(-95,25),life:rand(.22,.62),max:.62,r:rand(1.3,3.8),color})}
function impact(s){const blast=s.kind==='shell'||s.kind==='arc',rad=s.splash;if(s.targetUnit&&s.targetUnit.hp>0)damageTarget(s.targetUnit,s.damage,s.team);if(rad){for(const u of units){if(u!==s.targetUnit&&u.team!==s.team&&u.hp>0&&Math.abs(u.x-s.tx)<rad)damageTarget(u,Math.max(4,s.damage*(1-Math.abs(u.x-s.tx)/rad)*.72),s.team)}}if(s.targetBase){if(s.targetBase===1){enemyHp=Math.max(0,enemyHp-s.damage);texts.push({x:s.tx,y:s.ty-20,value:'-'+s.damage,life:1.05,color:'#ffd18b'});if(enemyHp<=0)endGame(true)}else{playerHp=Math.max(0,playerHp-s.damage);texts.push({x:s.tx,y:s.ty-20,value:'-'+s.damage,life:1.05,color:'#ff8e86'});if(playerHp<=0)endGame(false)}}burst(s.tx,s.ty,blast?16:6,blast?'#ffb465':'#ffe6ad');if(blast)shake=Math.max(shake,2.4);updateHud()}
function update(dt){if(finished)return;elapsed+=dt;money+=10*dt;spawnTimer-=dt;if(spawnTimer<=0){const choices=['soldier','soldier','tank','artillery'];spawn(1,choices[Math.floor(Math.random()*choices.length)]);spawnTimer=rand(4,7)}
for(const u of units){u.cool-=dt;u.anim+=dt*8;u.flash=Math.max(0,u.flash-dt);const spec=TYPES[u.type],dir=u.team?-1:1,target=chooseTarget(u);let blocker=units.filter(v=>v.team!==u.team&&v.hp>0).find(v=>Math.abs(v.x-u.x)<(u.type==='tank'?30:19));if(target){if(u.cool<=0)fire(u,target)}else if(!blocker){u.x+=dir*spec.speed*dt}u.x=Math.max(18,Math.min(w-18,u.x))}
for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.age+=dt;const t=Math.min(1,s.age/s.flight);s.x=s.sx+(s.tx-s.sx)*t;s.y=s.kind==='arc'?s.sy+(s.ty-s.sy)*t-Math.sin(t*Math.PI)*Math.min(105,Math.abs(s.tx-s.sx)*.28):s.sy+(s.ty-s.sy)*t;if(t>=1){impact(s);shots.splice(i,1)}}
for(let i=units.length-1;i>=0;i--)if(units[i].hp<=0)units.splice(i,1);
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=115*dt;if(p.life<=0)particles.splice(i,1)}
for(let i=texts.length-1;i>=0;i--){const t=texts[i];t.life-=dt;t.y-=22*dt;if(t.life<=0)texts.splice(i,1)}
updateHud()}

