function silhouette(points,color='#0b0a12'){ctx.fillStyle=color;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fill()}
function drawCloud(x,y,s){ctx.fillStyle='rgba(48,39,56,.34)';ctx.beginPath();ctx.ellipse(x,y,52*s,10*s,0,0,Math.PI*2);ctx.ellipse(x-22*s,y-4*s,24*s,9*s,0,0,Math.PI*2);ctx.ellipse(x+13*s,y-8*s,31*s,12*s,0,0,Math.PI*2);ctx.fill()}
function drawLandscape(){const gy=groundY();const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#26223a');sky.addColorStop(.4,'#795066');sky.addColorStop(.72,'#e28b68');sky.addColorStop(1,'#f4b77a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
const glow=ctx.createRadialGradient(w*.52,gy*.53,4,w*.52,gy*.53,h*.42);glow.addColorStop(0,'rgba(255,215,151,.56)');glow.addColorStop(.32,'rgba(255,177,128,.19)');glow.addColorStop(1,'rgba(255,165,120,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);
ctx.fillStyle='#ffe2aa';ctx.globalAlpha=.88;ctx.beginPath();ctx.arc(w*.52,gy*.51,Math.min(45,w*.07),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
// distant cloud bands and layered, static mountain silhouettes
for(let i=0;i<5;i++){const x=((i*197+60)%Math.max(w,1));drawCloud(x,h*(.18+(i%3)*.07),.7+(i%2)*.34)}
silhouette([[0,gy-92],[w*.08,gy-130],[w*.16,gy-98],[w*.27,gy-150],[w*.36,gy-96],[w*.49,gy-128],[w*.61,gy-88],[w*.72,gy-141],[w*.83,gy-102],[w*.93,gy-139],[w,gy-91],[w,gy],[0,gy]],'#33283b');
silhouette([[0,gy-52],[w*.12,gy-83],[w*.22,gy-57],[w*.32,gy-91],[w*.45,gy-53],[w*.58,gy-79],[w*.7,gy-48],[w*.82,gy-88],[w*.92,gy-55],[w,gy-71],[w,gy],[0,gy]],'#211d2b');
// silhouettes of ruined walls and sparse dead trees
const decor=[[w*.22,gy-31,.8],[w*.76,gy-27,.65],[w*.43,gy-20,.45]];for(const [x,y,s] of decor){ctx.save();ctx.translate(x,y);ctx.scale(s,s);silhouette([[0,0],[0,-25],[-7,-25],[-7,-43],[1,-43],[1,-34],[9,-34],[9,-52],[16,-52],[16,-22],[23,-22],[23,0]],'#171520');ctx.restore()}
for(let i=0;i<7;i++){const x=((i*83+18)%Math.max(w,1)),y=gy-80-(i%3)*25;ctx.strokeStyle='rgba(32,25,38,.68)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x-6,y);ctx.quadraticCurveTo(x,y-5,x+6,y);ctx.stroke()}
// foreground earth and jagged edge
ctx.fillStyle='#100f17';ctx.fillRect(0,gy,w,h-gy);silhouette([[0,gy+4],[w*.1,gy-3],[w*.2,gy+2],[w*.31,gy-4],[w*.43,gy+3],[w*.57,gy-2],[w*.69,gy+3],[w*.81,gy-4],[w*.91,gy+2],[w,gy-2],[w,gy+11],[0,gy+11]],'#0c0b12');
ctx.strokeStyle='rgba(255,204,120,.18)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,gy+11);ctx.lineTo(w,gy+11);ctx.stroke();
}
function drawBase(team){const x=baseX(team),gy=groundY(),left=team===0,hp=team?enemyHp:playerHp;ctx.save();ctx.translate(x,gy);ctx.scale(left?1:-1,1);ctx.fillStyle='#0a0910';
// blockhouse, crenellated towers, narrow windows
ctx.beginPath();ctx.moveTo(-44,0);ctx.lineTo(-40,-63);ctx.lineTo(-30,-63);ctx.lineTo(-30,-78);ctx.lineTo(-19,-78);ctx.lineTo(-19,-63);ctx.lineTo(-12,-63);ctx.lineTo(-9,-98);ctx.lineTo(9,-98);ctx.lineTo(12,-63);ctx.lineTo(20,-63);ctx.lineTo(20,-78);ctx.lineTo(31,-78);ctx.lineTo(31,-63);ctx.lineTo(41,-63);ctx.lineTo(45,0);ctx.closePath();ctx.fill();
ctx.fillRect(-53,-7,106,8);ctx.fillRect(-48,-24,96,7);ctx.fillRect(-14,-114,28,17);ctx.fillRect(-4,-128,8,14);
ctx.fillStyle='#f1ad6e';ctx.globalAlpha=.78;for(const xx of [-33,-8,18,34]){ctx.fillRect(xx,-49,3,11)}ctx.globalAlpha=1;
